<script>
 import {getContext,onMount,tick} from 'svelte';
 import {CONTEXT,safeURL} from './context.js';
 import {parseMemoMarkdown,normalizeTags,DraftStore} from '../core/data.js';
 import RichEditor from '../editor/RichEditor.svelte';
 import Button from '../components/Button.svelte';
 const {options,shared}=getContext(CONTEXT),{repository,t,renderMarkdown,renderBlockDOM,openBlock,beforeCompose}=options;
 let {layout,stats,onclose,onopen,onnotify,onsaved,onsettings,onformat}= $props();
 let sheet,file,editor,element,candidates,images=$state([]),busy=$state(false),uploading=$state(false),draftId=$state('new'),editingMemo=null,stale=true,opened=false,dead=false;
 let value=$state(''),active=$state({}),tagOptions=$state([]),candidate=$state(-1),candidateLeft=$state(8),candidateTop=$state(8),tagName='',dismissedTag=null,timer;
 let storage;try{storage=options.container.ownerDocument.defaultView.localStorage;}catch{storage=null;}
 const drafts=new DraftStore(storage),doc=options.container.ownerDocument,win=doc.defaultView;
 let inline=$derived(layout==='desktop');
 export function flushDraft(){clearTimeout(timer);if(editor&&(inline?!stale:opened)&&!busy){try{if(!drafts.save(draftId,{text:editor.value(),images:images.slice()}))onnotify('draftUnavailable');}catch{onnotify('draftUnavailable');}}}
 function queueDraft(){clearTimeout(timer);timer=setTimeout(flushDraft,300);}
 export function place(target){if(!sheet||!target)return;const focused=sheet.contains(doc.activeElement);flushDraft();target.append(sheet);if(inline&&!busy&&!uploading)loadDraft(editingMemo);else stale=true;if(focused){if(inline)element.focus();else compose(editingMemo);}resizeInput();}
 export function resizeInput(){if(!element)return;const min=inline?48:116,max=inline?360:Math.max(116,(win.visualViewport?.height||win.innerHeight)-200);element.style.height='auto';element.style.height=Math.max(min,Math.min(element.scrollHeight,max))+'px';}
 function editorHTML(memo,attachments){const template=doc.createElement('template');template.innerHTML=renderBlockDOM(memo.dom);for(const path of attachments.slice().reverse()){const imgs=[...template.content.querySelectorAll('img')].filter(img=>(img.getAttribute('src')||'').replace(/^\//,'')===path);const img=imgs.pop();if(img){const parent=img.parentElement;img.remove();if(parent&&!parent.textContent.trim()&&!parent.querySelector('img'))parent.remove();}}return template.innerHTML;}
 export function loadDraft(memo){if(!editor)return;editingMemo=memo||null;draftId=memo?.id||'new';let saved;try{saved=drafts.load(draftId);}catch{onnotify('draftUnavailable');}const original=memo?parseMemoMarkdown(memo.markdown):{text:'',images:[]};editor.load(saved?.text??original.text,saved?undefined:memo&&renderBlockDOM?editorHTML(memo,original.images):undefined);value=editor.value();images=(saved?.images||original.images||[]).filter(p=>safeURL(p,true));stale=false;tagOptions=[];tick().then(resizeInput);}
 export async function compose(memo){if(!editor){await tick();if(!editor)return;}if(busy||uploading||beforeCompose&&!beforeCompose())return;if(memo&&!editor.canEdit(parseMemoMarkdown(memo.markdown).text)){onnotify('nativeEditRequired');openBlock(memo.id);return;}flushDraft();loadDraft(memo);opened=true;onopen();await tick();element.focus();resizeInput();if(!memo&&!shared.settings.notebook){closeCompose();onsettings(true);}}
 export function closeCompose(){if(busy||uploading)return;if(inline){if(draftId!=='new')compose();else element?.blur();return;}flushDraft();opened=false;onclose();}
 export function releaseComposer(){if(busy||uploading)return false;if(inline){flushDraft();stale=true;}else if(opened)closeCompose();return true;}
 export function isEditing(){return draftId!=='new';}
 export function command(key){editor?.command(key);}
 export function canEdit(markdown){return editor?.canEdit(markdown)||false;}
 export function hasDraft(id){return drafts.load(id);}
 export function removeDraft(id){drafts.remove(id);}
 export async function reloadMemo(id){if(draftId===id)loadDraft(await repository.get(id));}
 export function draftHasNativeTag(text){if(!renderMarkdown)return false;const template=doc.createElement('template');template.innerHTML=renderMarkdown(normalizeTags(text));return [...template.content.querySelectorAll('[data-type~="tag"],em')].some(node=>{if(node.closest('code,pre'))return false;const value=node.textContent.replace(/[\u200b\u2060]/g,'').trim();return node.getAttribute('data-type')?.split(' ').includes('tag')?value.replace(/^#|#$/g,'')==='轻墨':value==='#轻墨#';});}
 async function submit(){if(busy||uploading||(!value.trim()&&!images.length))return;if(draftId==='new'&&!shared.settings.notebook){onsettings(true);return;}if(editingMemo?.external&&editingMemo.marker!=='1'&&editingMemo.tags.includes('轻墨')&&!draftHasNativeTag(editor.value())&&!win.confirm(t('editRemovesTagConfirm')))return;flushDraft();busy=true;try{await repository.save({id:draftId==='new'?undefined:draftId,text:editor.value(),images:images.slice()},shared.settings);}catch(error){if(dead)return;busy=false;onnotify(error.code==='HISTORY_SNAPSHOT_FAILED'?'historySnapshotFailed':error.code==='MEMO_STRUCTURED_EDIT'?'structuredEditFailed':'saveFailed');element.focus();return;}if(dead)return;try{drafts.remove(draftId);}catch{onnotify('draftUnavailable');}busy=false;editor.load('');value='';images=[];draftId='new';editingMemo=null;tagOptions=[];if(!inline){opened=false;onclose();}await onsaved();resizeInput();if(inline)element.focus();}
 async function upload(e){const files=[...e.currentTarget.files];e.currentTarget.value='';if(!files.length)return;uploading=true;onnotify('uploading');try{const paths=await repository.upload(files);if(!dead){images.push(...paths);onnotify('uploaded');}}catch(error){if(!dead){images.push(...(error.paths||[]));onnotify('uploadFailed');}}finally{if(!dead){uploading=false;images=images.filter(p=>safeURL(p,true));flushDraft();}}}
 async function tagCandidates(){editor.highlightToken();const token=editor.token();if(!token){tagOptions=[];tagName='';candidate=-1;dismissedTag=null;return;}if(token.name!==tagName){candidate=-1;dismissedTag=null;}tagName=token.name;if(dismissedTag===tagName)return;tagOptions=(stats.tags||[]).filter(x=>x.name.toLocaleLowerCase().includes(token.name.toLocaleLowerCase())).sort((a,b)=>String(b.lastUsed).localeCompare(String(a.lastUsed))).slice(0,6);if(token.name&&!(stats.tags||[]).some(x=>x.name.toLocaleLowerCase()===token.name.toLocaleLowerCase()))tagOptions.push({name:token.name,create:true});await tick();if(!candidates||!tagOptions.length)return;const caret=token.range.getBoundingClientRect(),box=sheet.getBoundingClientRect();candidateLeft=Math.max(8,Math.min(caret.left-box.left,box.width-candidates.offsetWidth-8));const below=caret.bottom-box.top+sheet.scrollTop+4;candidateTop=below+candidates.offsetHeight>sheet.scrollTop+box.height?Math.max(sheet.scrollTop+8,caret.top-box.top+sheet.scrollTop-candidates.offsetHeight-4):below;}
 function complete(name){editor.completeTag(name);candidate=-1;dismissedTag=null;tagOptions=[];}
 function keydown(e){if(e.isComposing||editor.composing||e.keyCode===229)return;if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();submit();return;}const token=editor.token();if(!token)return;if(e.key==='Escape'){e.preventDefault();e.stopPropagation();dismissedTag=token.name;tagOptions=[];return;}if((e.key==='ArrowDown'||e.key==='ArrowUp')&&tagOptions.length){e.preventDefault();candidate=candidate<0?(e.key==='ArrowDown'?0:tagOptions.length-1):(candidate+(e.key==='ArrowDown'?1:-1)+tagOptions.length)%tagOptions.length;return;}if(e.key==='Enter'&&token.name){e.preventDefault();e.stopPropagation();complete(candidate>=0?tagOptions[candidate].name:((stats.tags||[]).find(x=>x.name.toLocaleLowerCase()===token.name.toLocaleLowerCase())?.name||token.name));}}
 function ready(api,node){editor=api;element=node;if(inline)loadDraft();}
 function selection(api){active=Object.fromEntries(['bold','underline','highlight','unordered','ordered','quote'].map(key=>[key,api.active(key)]));}
 onMount(()=>{const visibility=()=>{if(doc.hidden)flushDraft();};doc.addEventListener('visibilitychange',visibility);win.addEventListener('pagehide',flushDraft);return()=>{flushDraft();dead=true;clearTimeout(timer);doc.removeEventListener('visibilitychange',visibility);win.removeEventListener('pagehide',flushDraft);};});
</script>
<section bind:this={sheet} class="qm-sheet" role={inline?'region':'dialog'} aria-modal={inline?undefined:true} aria-label={t(draftId==='new'?'compose':'edit')}>
 <Button label={t('closeInput')} class="qm-handle" onclick={closeCompose}><span></span></Button>
 <RichEditor {renderMarkdown} label={t(draftId==='new'?'compose':'edit')} placeholder={t('inputPlaceholder')} disabled={busy} onready={ready} onchange={api=>{value=api.value();queueDraft();resizeInput();tagCandidates();}} onselection={selection} onkeydown={keydown} onkeyup={e=>{if(!e.isComposing&&!editor.composing&&!['Enter','Escape','ArrowDown','ArrowUp'].includes(e.key))tagCandidates();}} onfocus={()=>{if(inline&&stale&&!busy&&!uploading&&(!beforeCompose||beforeCompose()))loadDraft(editingMemo);}}/>
 <div class="qm-previews">{#each images as path,i}<div class="qm-preview"><img src={safeURL(path,true)} alt={t('attachedImage')}/><Button label={t('removeImage')} icon="close" disabled={busy||uploading} onclick={()=>{images.splice(i,1);queueDraft();}}/></div>{/each}</div>
 <div bind:this={candidates} class="qm-candidates" role="listbox" aria-label={t('tags')} style:left={candidateLeft+'px'} style:top={candidateTop+'px'}>{#each tagOptions as tag,i}<button type="button" class="qm-tag-option" role="option" aria-selected={candidate===i} onmousedown={e=>e.preventDefault()} onclick={()=>complete(tag.name)}>#{tag.name}{#if tag.create}<small class="qm-tag-create">{t('createTag')}</small>{/if}</button>{/each}</div>
 <!-- svelte-ignore a11y_no_static_element_interactions -->
 <div class="qm-tools" onmousedown={e=>{if(e.target.closest('button'))e.preventDefault();}}>
  <Button label={t('tag')} icon="hash" disabled={busy||uploading} onclick={()=>editor.insert('#')}/><Button label={t('addImage')} icon="image" disabled={busy||uploading} onclick={()=>file.click()}/><i class="qm-divider"></i>
  {#each [['bold','bold',''],['underline','underline','qm-format-inline'],['highlight','highlight','qm-format-inline'],['unordered','list',''],['ordered','ordered','qm-format-inline'],['quote','quote','qm-format-inline']] as [key,icon,cls]}<Button label={t(key)} {icon} class={cls} disabled={busy||uploading} aria-pressed={!!active[key]} onclick={()=>editor.command(key)}/>{/each}
  <Button label={t('formatMore')} icon="more" class="qm-format-more" disabled={busy||uploading} onclick={e=>onformat(e.currentTarget)}/>
  <Button label={t('cancel')} class="qm-cancel-edit" hidden={!(inline&&draftId!=='new')} disabled={busy||uploading} onclick={closeCompose}/><Button label={t(draftId==='new'?'send':'saveEdit')} icon="send" class="qm-send" aria-busy={busy} disabled={busy||uploading||(!value.trim()&&!images.length)} onclick={submit}/>
 </div>
 <input bind:this={file} type="file" accept="image/*" multiple hidden disabled={busy||uploading} onchange={upload}/>
</section>
